// Corona Glow and Stars - the light of a star without its disk: a flaring
// glow over a swirling nebula and a drifting, twinkling star field.
// Parametric (u,v), animated. Seam-free. Same sky as "Corona and Stars"; here
// the star itself is hidden and only its light is drawn.
//
// HOW IT CLOSES
//  - Star field: three layers of cells, whole numbers of cells per turn and
//    wrapped indices; at most one star per cell, each with its own size,
//    color and twinkle.
//  - Nebula: a self-warping flow of sines computed on the flat 4D torus
//    (cos 2pi u, sin 2pi u, cos 2pi v, sin 2pi v): nothing to join.
//  - Glow: the distance is taken to the NEAREST copy of the star across the
//    seams, so the light can sit anywhere, even on a seam; it fades to zero
//    before the half-turn where the nearest copy changes. Inside the radius
//    of the hidden star the light keeps rising, without an edge, to a hot
//    center.
// Twisted gluing (Klein bottle, Moebius band): set MIRROR_V to 1.0 (the glow
// then appears twice, mirrored).
// Dock colors: u_col1 = glow, u_col2 = nebula.

const float SUN_U    = 0.25;   // position of the light (turns along u)
const float SUN_V    = 0.50;   // position of the light (turns along v)
const float SUN_SIZE = 0.08;   // radius of the hidden star (turns): size of
                               // the glow, 0 = no glow                 [0 .. 0.15]
const float ASPECT   = 1.0;    // >1 squeezes the glow along u          [0.3 .. 3]
const float CORONA   = 1.0;    // brightness of the glow                [0 .. 2]
const float CORE     = 0.4;    // extra white heat at the center        [0 .. 2]
const float NEBULA   = 1.0;    // nebula brightness                     [0 .. 2]
const float STARS    = 1.0;    // star brightness                       [0 .. 2]
const float STAR_CELLS = 40.0; // cells of the coarsest star layer per turn (whole)
const float SPEED    = 1.0;    // overall animation speed (0 = still)
const float GAS_SPEED = 0.35;  // swirling of the nebula                [0 .. 1]
const float STAR_DRIFT = 0.006; // drift of the nearest stars along u (turns per
                               // second); farther layers move slower: parallax
const float TWINKLE  = 0.85;   // depth of the twinkle                  [0 .. 1]
const float FLARES   = 0.25;   // speed of the flames leaving the star  [0 .. 1]
const float MIRROR_U = 0.0;    // 1 = fold u
const float MIRROR_V = 0.0;    // 1 = fold v (Klein bottle, Moebius band)

// ---- seam-free toolkit: every grid has a whole number of cells per turn and
// ---- every cell index is wrapped, so the pattern repeats exactly at u, v = 0/1
vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);   // 0 -> 0.5 -> 0: equal at both ends
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

// random value of cell c, wrapped into the period n (negative indices too):
// the same cell one turn away gets the same value.
// NB: helper functions here return float/vecN only -- the per-mesh renamer of
// the engine recognizes those return types, not ivec2.
float cellHash(ivec2 c, ivec2 n, int salt) {
    ivec2 w = ivec2(mod(vec2(c), vec2(n)));
    uint h = uint(w.x) * 0x8da6b343u + uint(w.y) * 0xd8163841u + uint(salt) * 0xcb1ab31fu;
    h ^= h >> 15; h *= 0x2c1b3c6du;
    h ^= h >> 12; h *= 0x297a2d39u;
    h ^= h >> 15;
    return float(h >> 8) * (1.0 / 16777216.0);
}

vec2 cellHash2(ivec2 c, ivec2 n, int salt) {
    return vec2(cellHash(c, n, salt), cellHash(c, n, salt + 101));
}

// value noise with a period of n cells; uv in turns (0..1 = one turn)
float pnoise(vec2 uv, ivec2 n, int salt) {
    vec2 p = uv * vec2(n);
    ivec2 i = ivec2(floor(p));
    vec2 f = fract(p);
    vec2 w = f * f * (3.0 - 2.0 * f);
    float a = cellHash(i, n, salt);
    float b = cellHash(i + ivec2(1, 0), n, salt);
    float c = cellHash(i + ivec2(0, 1), n, salt);
    float d = cellHash(i + ivec2(1, 1), n, salt);
    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

// fractal sum: each octave doubles the cells, so it stays periodic
float pfbm(vec2 uv, ivec2 n, int octaves, int salt) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int o = 0; o < 6; o++) {
        if (o >= octaves) break;
        sum += amp * pnoise(uv, n, salt + 17 * o);
        norm += amp;
        amp *= 0.5;
        n *= 2;
    }
    return sum / norm;
}

// Voronoi on a grid of n cells per turn (p in cells). Returns
//   x = distance to the nearest point, y = distance to the nearest border,
//   z = random id of the nearest cell.
// rel = p minus the nearest point; edgeDir = unit vector toward the nearest
// border (the downhill direction of anything that rises from the borders).
vec3 pvoronoi(vec2 p, ivec2 n, float jitter, int salt, out vec2 rel, out vec2 edgeDir) {
    ivec2 ip = ivec2(floor(p));
    vec2 fp = fract(p);
    float best = 1.0e9;
    ivec2 bestCell = ivec2(0);
    vec2 bestPt = vec2(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        ivec2 g = ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 dv = pt - fp;
        float dd = dot(dv, dv);
        if (dd < best) { best = dd; bestCell = g; bestPt = pt; }
    }
    float border = 1.0e9;
    edgeDir = vec2(1.0, 0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        if (i == 0 && j == 0) continue;
        ivec2 g = bestCell + ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 ab = pt - bestPt;
        float lab = length(ab);
        if (lab < 1.0e-5) continue;
        vec2 dir = ab / lab;
        float dist = dot(0.5 * (bestPt + pt) - fp, dir);
        if (dist < border) { border = dist; edgeDir = dir; }
    }
    rel = fp - bestPt;
    return vec3(sqrt(best), border, cellHash(ip + bestCell, n, salt + 7));
}

vec4 torusPoint(vec2 uv, float radius) {
    vec2 a = TAU * uv;
    return radius * vec4(cos(a.x), sin(a.x), cos(a.y), sin(a.y));
}

vec3 starLayer(vec2 uv, ivec2 n, int salt, float time) {
    vec2 p = uv * vec2(n);
    ivec2 ip = ivec2(floor(p));
    vec2 fp = fract(p);
    vec3 acc = vec3(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        ivec2 w = ip + ivec2(i, j);
        float h = cellHash(w, n, salt);
        if (h > 0.6) continue;                         // empty cell
        vec2 dv = fp - (vec2(i, j) + 0.15 + 0.7 * cellHash2(w, n, salt + 3));
        float d2 = dot(dv, dv);
        float size = cellHash(w, n, salt + 5);
        float core = exp(-d2 / (0.0006 + 0.0025 * size * size));
        float halo = 0.0015 * size / (d2 + 0.002) * smoothstep(1.2, 0.2, sqrt(d2));
        // four-pointed glint on the brightest ones
        float glint = (exp(-abs(dv.x) * 90.0) * exp(-abs(dv.y) * 9.0)
                     + exp(-abs(dv.y) * 90.0) * exp(-abs(dv.x) * 9.0)) * smoothstep(0.8, 1.0, size);
        float rate = 1.0 + 3.5 * cellHash(w, n, salt + 9);
        float tw = 0.5 + 0.5 * sin(time * rate + TAU * h * 7.0);
        float twinkle = 1.0 - TWINKLE * (1.0 - tw * tw);
        vec3 tint = mix(vec3(0.62, 0.74, 1.0), vec3(1.0, 0.78, 0.52), cellHash(w, n, salt + 11));
        acc += tint * (core + halo + 0.8 * glint) * twinkle * (0.25 + 0.75 * size);
    }
    return acc;
}

// fixed 4D turn between octaves
vec4 turn4(vec4 p) {
    p.xz = mat2(0.80, 0.60, -0.60, 0.80) * p.xz;
    p.yw = mat2(0.28, 0.96, -0.96, 0.28) * p.yw;
    p.xy = mat2(0.96, -0.28, 0.28, 0.96) * p.xy;
    p.zw = mat2(0.60, -0.80, 0.80, 0.60) * p.zw;
    return p;
}

// gas: sines of the point push the point (domain warping), octave after octave
float gasFlow(vec4 p, float time, int octaves) {
    float acc = 0.0;
    float amp = 1.0;
    float norm = 0.0;
    float freq = 1.7;
    for (int i = 0; i < 6; i++) {
        if (i >= octaves) break;
        p += 0.5 * sin(p.wxyz * freq + time * (0.6 + 0.21 * float(i)));
        acc += amp * abs(dot(cos(p), sin(p.zwxy)));
        norm += amp;
        amp *= 0.72;
        freq *= 1.31;
        p = 1.47 * turn4(p);
    }
    return acc / norm;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = seamFold(fragCoord / iResolution.xy);
    float time = iTime * SPEED;

    // ---- nebula: gas density from one flow, warm/cool tint from another
    vec2 gasUV = uv + vec2(0.4 * STAR_DRIFT * time, 0.0);
    float gas = gasFlow(torusPoint(gasUV, 1.2), GAS_SPEED * time, 6);
    float warm = gasFlow(torusPoint(gasUV + vec2(0.37, 0.21), 0.85), 0.8 * GAS_SPEED * time, 4);
    float dens = clamp((gas - 0.85) / 0.65, 0.0, 1.0);
    dens *= dens;
    vec3 nebCol = mix(u_col2, u_col1 * vec3(1.0, 0.75, 0.55), clamp((warm - 0.6) / 0.8, 0.0, 1.0));
    vec3 col = NEBULA * nebCol * dens * 1.5;

    // ---- stars: three depths
    int sc = int(STAR_CELLS);
    float drift = STAR_DRIFT * time;                // shift along u: keeps the period
    vec3 stars = starLayer(uv + vec2(drift, 0.0), ivec2(sc), 7, time)
               + 0.8 * starLayer(uv + vec2(0.6 * drift, 0.0), ivec2(sc * 2), 19, time)
               + 0.6 * starLayer(uv + vec2(0.35 * drift, 0.0), ivec2(sc * 4), 31, time);
    col += STARS * stars * (1.0 - 0.5 * dens);

    // ---- the light of the hidden star
    if (SUN_SIZE > 0.0) {
        vec2 d0 = uv - vec2(SUN_U, SUN_V);
        d0 -= floor(d0 + 0.5);                          // nearest copy across the seams
        vec2 d = d0 * vec2(ASPECT, 1.0);
        float r = length(d) / SUN_SIZE;                 // 1 = radius of the hidden star
        float reach = smoothstep(0.49, 0.30, max(abs(d0.x), abs(d0.y)));

        // flames: noise in (angle, log radius), periodic in the angle, moving out
        float ang = atan(d.y, d.x) / TAU;
        vec2 fl = vec2(ang, 0.35 * log(max(r, 0.05)) - FLARES * time);
        float flame = pfbm(fl, ivec2(18, 3), 4, 5);
        float rays = pfbm(vec2(ang + 0.01 * time, 0.3 * FLARES * time), ivec2(40, 2), 3, 9);

        // rim < 0 inside the hidden star. Outside (rim > 0) this is the light of
        // "Corona and Stars" unchanged; inside the same curves simply go on
        // rising with the same slope, so there is no edge where the disk was.
        float rim = r - 1.0;
        float outside = max(rim, 0.0);
        float reachL = 0.25 + 1.1 * flame * flame + 0.6 * rays * rays;
        float corona = exp(min(-rim / reachL, 3.0));
        corona += 0.35 * exp(min(-rim * 0.6, 3.0));     // wide soft glow
        corona *= CORONA * reach * (0.9 + 0.1 * sin(1.3 * time));
        vec3 coronaCol = mix(u_col1 * vec3(1.15, 0.75, 0.45), u_col1, exp(-outside));
        col += coronaCol * corona * 1.6;

        // extra white heat toward the center: (1 - r^2)^2 is 0 with zero slope
        // at r = 1, so it adds no edge either
        float inner = max(1.0 - r * r, 0.0);
        inner *= inner;
        col += mix(u_col1, vec3(1.0, 0.96, 0.88), 0.6) * CORE * inner * (0.85 + 0.3 * rays) * reach;
    }

    // soft tone mapping: bright cores roll off instead of clipping
    col = 1.0 - exp(-col * 1.3);
    fragColor = vec4(col, 1.0);
}
